DROP TABLE IF EXISTS `skill_discovery_template`;
CREATE TABLE `skill_discovery_template` (
  `spellId` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'SpellId of the discoverable spell',
  `reqSpell` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'spell requirement',
  `reqSkillValue` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'skill points requirement',
  `chance` float NOT NULL DEFAULT 0 COMMENT 'chance to discover',
  PRIMARY KEY (`spellId`,`reqSpell`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Skill Discovery System';


